class GridTotals {
  private P: number[][];

  constructor(grid: number[][]) {
    const R = grid.length, C = grid[0].length;
    this.P = Array.from({ length: R + 1 }, () => new Array<number>(C + 1).fill(0));
    for (let r = 0; r < R; r++)
      for (let c = 0; c < C; c++)
        this.P[r + 1][c + 1] = grid[r][c] + this.P[r][c + 1] + this.P[r + 1][c] - this.P[r][c];
  }

  regionTotal(r1: number, c1: number, r2: number, c2: number): number {
    const P = this.P;
    return P[r2 + 1][c2 + 1] - P[r1][c2 + 1] - P[r2 + 1][c1] + P[r1][c1];
  }
}

